import json,pathlib,sys
from playwright.sync_api import sync_playwright,expect
root=pathlib.Path(__file__).resolve().parents[1]
errors=[];checks=[]
with sync_playwright() as p:
    browser=p.chromium.launch(headless=True,args=['--no-sandbox'])
    ctx=browser.new_context(viewport={'width':1440,'height':960},reduced_motion='reduce')
    page=ctx.new_page();page.on('pageerror',lambda e:errors.append(str(e)))
    page.goto('http://127.0.0.1:8000/',wait_until='networkidle');expect(page.locator('#auth')).to_be_visible()
    page.locator('#demo-patient').click();page.locator('#auth-submit').click();expect(page.locator('#portal')).to_be_visible();expect(page.locator('#workbody h1')).to_contain_text('Alex');checks.append('Server patient login and assigned doctor dashboard')
    page.screenshot(path=str(root/'dashboard-desktop.png'),full_page=False)
    page.locator('#portal-nav [data-page="doctors"]').click();expect(page.locator('#doctor-grid article')).to_have_count(40)
    page.locator('#doctor-search').fill('Maya');expect(page.locator('#doctor-grid article')).to_have_count(1);checks.append('40 doctor directory and search')
    page.locator('#portal-nav [data-page="intake"]').click();expect(page.locator('#f-gender')).not_to_have_attribute('required','')
    page.evaluate('intake.pain_map=[]');page.locator('#f-name').fill('Alex Sample');page.locator('#f-gender').select_option('')
    page.locator('[data-step="4"]').click();expect(page.locator('#include-repro')).to_be_visible();expect(page.locator('#intake-fields')).to_be_hidden()
    page.locator('#include-repro').check();expect(page.locator('#intake-fields')).to_be_visible();page.locator('#include-repro').uncheck()
    page.locator('[data-step="6"]').click();page.locator('#marker-x').fill('50');page.locator('#marker-y').fill('30');page.locator('#add-marker').click();expect(page.locator('#marker-list button')).to_have_count(1)
    page.locator('#intake-consent').check();page.locator('#submit-intake').click();expect(page.locator('#save-state')).to_contain_text('Saved');checks.append('Optional gender, opt-in reproductive section, accessible pain map, submission')
    page.locator('#portal-nav [data-page="meridians"]').click();expect(page.locator('.meridiancard')).to_have_count(14)
    assert page.locator('.meridianimg').evaluate('(img)=>img.complete && img.naturalWidth>0');page.locator('#meridian-search').fill('Lung');expect(page.locator('.meridiancard')).to_have_count(1);checks.append('Uploaded image loads and 14 meridian search works')
    page.locator('#portal-nav [data-page="messages"]').click();page.locator('#message-text').fill('Browser test: sample follow-up question.');page.locator('#message-form button').click();expect(page.locator('#chatlog')).to_contain_text('Browser test: sample follow-up question.');checks.append('Patient message saved')
    page.locator('#logout').click();expect(page.locator('#auth')).to_be_visible();page.locator('#demo-doctor').click();page.locator('#auth-submit').click();expect(page.locator('#workbody h1')).to_contain_text('Good care')
    page.locator('#portal-nav [data-page="clinical"]').click();page.locator('#patient-select').select_option(label='Alex Sample · patient@example.com');expect(page.locator('#care-form')).to_be_visible()
    f=page.locator('#care-form');f.locator('[name="title"]').fill('Browser-tested follow-up');f.locator('[name="assessment"]').fill('Sample consultation discussion. No diagnosis made.');f.locator('[name="suggestions"]').fill('Saved fictional suggestion: speak with your clinician about concerns.');f.locator('[name="prescription"]').fill('Sample only — no medication prescribed.');f.locator('[name="meridian"][value="LU"]').check();f.locator('input[type=checkbox][required]').check();f.locator('button').click();expect(page.locator('#patient-work')).to_contain_text('Browser-tested follow-up');checks.append('Doctor reviews assigned patient and publishes append-only consultation')
    page.locator('#portal-nav [data-page="messages"]').click();page.locator('#patient-select').select_option(label='Alex Sample · patient@example.com');expect(page.locator('#message-form')).to_be_visible();page.locator('#message-text').fill('Browser test: sample doctor reply.');page.locator('#message-form button').click();expect(page.locator('#chatlog')).to_contain_text('Browser test: sample doctor reply.');checks.append('Doctor receives question and saves reply')
    page.locator('#logout').click();page.locator('#demo-patient').click();page.locator('#auth-submit').click();page.locator('#portal-nav [data-page="history"]').click();expect(page.locator('#history-list')).to_contain_text('Browser-tested follow-up');page.locator('#history-search').fill('no medication');expect(page.locator('#history-list article')).not_to_have_count(0);checks.append('Returning patient sees prescriptions and past consultation notes')
    page.locator('#portal-nav [data-page="messages"]').click();expect(page.locator('#chatlog')).to_contain_text('Browser test: sample doctor reply.');checks.append('Returning patient sees saved doctor reply')
    page.locator('#portal-nav [data-page="settings"]').click()
    with page.expect_download() as dl: page.locator('#export-data').click()
    assert dl.value.suggested_filename=='my-acupuncture-records.json';checks.append('Patient record JSON export')
    ctx.close()
    local=browser.new_context(viewport={'width':1440,'height':960},reduced_motion='reduce');pg=local.new_page();pg.on('pageerror',lambda e:errors.append(str(e)))
    pg.goto((root/'Acupuncture-Interactive-Demo.html').as_uri());expect(pg.locator('#auth')).to_be_visible();pg.locator('#auth-switch').click();pg.locator('#auth-name').fill('Standalone Sample');pg.locator('#auth-email').fill('standalone@example.com');pg.locator('#auth-pass').fill('StandalonePass!2026');pg.locator('#auth-consent').check();pg.locator('#auth-submit').click();expect(pg.locator('#workbody h1')).to_contain_text('Standalone');checks.append('Standalone file patient registration and password hashing')
    pg.reload();expect(pg.locator('#workbody h1')).to_contain_text('Standalone');checks.append('Standalone session and account persistence on reload')
    pg.locator('#portal-nav [data-page="overview"]').click();pg.screenshot(path=str(root/'standalone-desktop.png'),full_page=False)
    local.close()
    mobile=browser.new_context(viewport={'width':390,'height':844},is_mobile=True,device_scale_factor=1,reduced_motion='reduce');mp=mobile.new_page();mp.on('pageerror',lambda e:errors.append(str(e)))
    mp.goto((root/'Acupuncture-Interactive-Demo.html').as_uri());mp.locator('#demo-patient').click();mp.locator('#auth-submit').click();expect(mp.locator('#workbody h1')).to_contain_text('Alex')
    assert mp.evaluate('document.documentElement.scrollWidth<=window.innerWidth')
    mp.screenshot(path=str(root/'dashboard-mobile.png'),full_page=False)
    mp.locator('#portal-menu').click();mp.locator('#portal-nav [data-page="doctors"]').click();expect(mp.locator('#doctor-grid article')).to_have_count(40);assert mp.evaluate('document.documentElement.scrollWidth<=window.innerWidth');checks.append('390px mobile layout, navigation and doctor directory')
    mobile.close();browser.close()
report={'checks':checks,'passed':len(checks),'javascript_errors':errors};(root/'browser-results.json').write_text(json.dumps(report,indent=2));print(json.dumps(report,indent=2))
if errors: sys.exit(1)
